// Input: HTML content from previous node 'Switch1'
const htmlContent = $('Switch1').first().json.html || ""; 

// Function to extract all http/https URLs
function extractUrlsFromHtml(html) {
    const urls = [];
    const regex = /https?:\/\/[^\s"'<>]+/g; // Matches http or https URLs

    let match;
    while ((match = regex.exec(html)) !== null) {
        urls.push(match[0]);
    }

    // Remove duplicates
    return [...new Set(urls)];
}

// Extract URLs
const extractedUrls = extractUrlsFromHtml(htmlContent);

// Map each URL to an object
const urlsArray = extractedUrls.map(u => ({ url: u }));

// Return in the requested format
return [{ json: { output: { urls: urlsArray } } }];
